/**
 * Metadata for [`DocumentTopicEvent::Created`].
 */
export type DocumentCreatedMetadata = {
    /**
     * Who mechanically created the document. Absent on events published
     * before attribution: ingest then treats [`Self::owner`] as the actor.
     */
    actor?: string | null;
    /**
     * Creation timestamp reported by the repository.
     */
    created_at?: string | null;
    /**
     * The id of the created document.
     */
    document_id: string;
    /**
     * The document name, with any file extension stripped.
     */
    document_name: string;
    file_type?: null | FileType;
    on_behalf_of?: null | MacroUserIdStr;
    /**
     * The owner (creator) of the document.
     */
    owner: MacroUserIdStr;
    /**
     * Project the document was created in, when any.
     */
    project_id?: string | null;
    sub_type?: null | DocumentSubType;
};

/**
 * Metadata for [`DocumentTopicEvent::Deleted`].
 */
export type DocumentDeletedMetadata = {
    actor_user_id?: null | MacroUserIdStr;
    /**
     * The id of the deleted document.
     */
    document_id: string;
    /**
     * Project the document belonged to, when any.
     */
    project_id?: string | null;
};

/**
 * The document filters used to filter down what documents you search over.
 */
export type DocumentFilters = {
    /**
     * Document ids to search over. Examples: ['doc1'], ['doc1', 'doc2']. Empty to search all accessible documents.
     */
    document_ids?: Array<string>;
    /**
     * Document file types to search. Examples: ['pdf'], ['md', 'txt']. Empty to search all file types.
     */
    file_types?: Array<string>;
    /**
     * Filter by document importance. None to ignore, true to pass through (no clause), false to short-circuit and return nothing.
     */
    importance?: boolean | null;
    /**
     * Filter by email attachment status. true = only email attachments, false = only non-email attachments, None = both.
     */
    is_email_attachment?: boolean | null;
    /**
     * Filter by document notification state.
     */
    notification_filters?: NotificationFilters;
    /**
     * Filter by document owner. Examples: ['macro|user1@user.com'], ['macro|user1@user.com', 'macro|user2@user.com']. Empty to search all owners.
     */
    owners?: Array<string>;
    /**
     * A list of project ids to search within. Examples: ['project1'].
     * filtering. Empty to ignore project filtering.
     */
    project_ids?: Array<string>;
    /**
     * Filter by document sub type. Examples: ['task']. Empty to search all sub types.
     */
    sub_types?: Array<string>;
    /**
     * Task-specific filters that only apply to task subtype documents.
     */
    task_filters?: TaskFilters;
};

/**
 * Metadata for [`DocumentTopicEvent::Interaction`].
 */
export type DocumentInteractionMetadata = {
    /**
     * The id of the document.
     */
    document_id: string;
    /**
     * What triggered this interaction.
     */
    reason: InteractionReason;
};

export type DocumentMetadata = {
    /**
     * The id of the document this document branched from
     */
    branchedFromId?: string | null;
    /**
     * The id of the version this document branched from
     * This could be either DocumentInstance or DocumentBom id depending on
     * the file type
     */
    branchedFromVersionId?: number | null;
    /**
     * The time the document was created
     */
    createdAt?: string | null;
    /**
     * The time the document was deleted
     */
    deletedAt?: string | null;
    /**
     * If the document is a DOCX document and unzipped, the document_bom will be present
     */
    documentBom?: Array<BomPart> | null;
    /**
     * The id of the document family this document belongs to
     */
    documentFamilyId?: number | null;
    /**
     * The document id
     */
    documentId: string;
    /**
     * The name of the document
     */
    documentName: string;
    /**
     * The version of the document
     * This could be the document_instance_id or document_bom_id depending on
     * the file type
     */
    documentVersionId: number;
    /**
     * The file type of the document (file extension)
     */
    fileType?: string | null;
    /**
     * The modification data for the document instance.
     * This is only used for PDF documents.
     */
    modificationData?: unknown;
    /**
     * The owner of the document
     */
    owner: string;
    /**
     * The id of the project that this document belongs to
     */
    projectId?: string | null;
    /**
     * The name of the project that this document belongs to
     */
    projectName?: string | null;
    /**
     * If the document is a PDF, this is the SHA of the pdf
     * If the document is a DOCX, this will not be present
     */
    sha?: string | null;
    subType?: null | DocumentSubType;
    /**
     * The time the document instance / document BOM was updated
     */
    updatedAt?: string | null;
};

